// TH14 v1.00b synthetic appearance alias used by this card.
// Native 0..23 map to the same target slot; native 24..42 map to target +1.
// Source etSprite(0, 5, 2): native type 5 -> TH14_BALL2, color 2 (valid 0..15).
// Catalog slot/radius only; not a byte-identical original asset claim.
const TH14_BALL2: int = 432;

// TH14 v1.00b Stage 7 Boss2 non-spell (Extra rank 4).
// Source: st07bs.ecl.txt:208-260 (Boss2 entry) + 262-292 (Boss2_at async).
// Source frame 0 is the Boss2 entry (timerReset at line 221); the card phase
// starts at card frame 0 and the real boss is spawned after OPENING_BUFFER plus
// task startup. Measured: boss spawns at card 124, source 141 first emission at
// card 266, so card frame = source frame + 125 for this enemy.

const TIME_LIMIT: int = 3424;
const OPENING_BUFFER: int = 120;

// Boss2_at line 273/287: %C = %RANDRAD, then %C += 0.174533f every 5-frame
// wave. Kept in 1/256 BAM so the ~10 degree step does not drift over ~572
// waves (0.174533 rad = 1820.4356 BAM -> 466032/256).
const WAVE_GAIN_256: int = 466032;
// Source slot0 timeout is 3000 frames (setInterrupt line 241; timerReset line
// 221). Boss2_at first runs at source frame 141 (wait 60 + wait 80, async next
// frame), so 572 five-frame waves cover source frames 141..2996; the next wave
// would start past the timeout. Extra 300 frames after the source stop are the
// phase tail for bullets already in flight.
const EMIT_ITERS: int = 572;

async sub pattern() {
    wait(OPENING_BUFFER);
    // Boss common entry position (Boss context line 17: movePos(0,128)).
    // Source LIFE = A+B = 14000 (line 219); no player DPS in this shell.
    _ = spawn_enemy(0fx, 128fx, 14000, 0, 0, 0, boss_main);
}

async sub boss_main() {
    set_invuln(65535);
    // Boss context lines 27-28: setHurtbox(48,48)/setHitbox(48,48); the normal
    // circle branch takes first value * 0.5, so both radii are 24.
    set_hitbox(24fx);
    set_hurtbox(24fx);

    // Entry lines 234-236: moveVel(0,0), moveVelTime(0,0,0,0) and
    // movePosTime(0,0,0,0) only clear residual velocity/position interpolation;
    // the independent card starts static at the Boss common (0,128).
    // Line 240: movePosTime(60, 4, 0, 128) from (0,128) -> zero displacement.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    // Line 246: moveLimit(0,128,280,64) = x [-140,140], y [96,160].
    // Enforced per step by card_arm_next_step below.
    wait(80);
    // Line 252: Boss2_at() async, first tick on the next source frame.
    spawn boss_emit();

    // Lines 254-258: wait(120); moveRand(60,4,1.0f); repeat. Source timeout at
    // frame 3000 ends the attack; the last moveRand inside it starts at 2900,
    // so 23 cycles (source 260..3020) cover the whole timed segment. The real
    // boss stays in place afterwards for the phase tail (no next attack).
    for cyc in 0..23 {
        card_move_rand();
        card_wait(120);
    }
    loop { wait(1); }
}

// moveRand sample from the TH16/TH18 movement recipe (speed 1 -> 0 over 60
// steps, linear; angleMode 4 does not change the speed slot). Limits here are
// this card's moveLimit(0,128,280,64): direction inner region x +-70,
// y 112..144; clamped position x [-140,140], y [96,160].
// Enemy shared slots: int0 = next step count, fx0/fx1 = logical unit vector.
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_move_rand() {
    // 412 moveRand: signed unit random * pi, unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Do not normalize this branch before the vertical abs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard (epsilon 0.05 rad -> nearest BAM 15862/16906).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Boss2_at (lines 262-292). Configured once: etAim(0,3) fixed-direction ring,
// etSprite(0,5,2), etCount(0,6,1), etAngle(0,C,pi/6), etSpeed(0,4,1) -> one
// layer so speed is 4. Mode 3 angle = alpha + 2*pi*i/6; with one layer the
// second angle is a layer offset and has no effect.
// etEx type 2 a=1 is ANIM; its birth backstep position -= 4*velocity is kept
// (speed 4 -> 16px opposite the bullet angle). etEx type 1048576 is BRIGHT and
// is presentation-only, omitted with the approved visual policy.
async sub boss_emit() {
    var c256: int = (rand(65536) - 32768) * 256;  // %C = %RANDRAD
    var n: int = 0;
    while n < EMIT_ITERS {
        // Line 277: circlePos(%A,%B,%RANDRAD,%RANDF*16.0f).
        var ang: angle = (rand(65536) - 32768) as angle;
        var u: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
        var rad: fx = u * 16fx;
        // Line 278: etOffsetAbs(0, A+FINAL_X, B+FINAL_Y).
        var bx: fx = $self_x + rad * cos(ang);
        var by: fx = $self_y + rad * sin(ang);
        var w: int = 0;
        while w < 10 {
            // Line 283: etOffsetRad(0,%RANDRAD,%RANDF*8.0f); line 284: etOn(0).
            var pang: angle = (rand(65536) - 32768) as angle;
            var pu: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
            var pr: fx = pu * 8fx;
            var sx: fx = bx + pr * cos(pang);
            var sy: fx = by + pr * sin(pang);
            // Lines 279/287: etAngle(0, %C, pi/6); six-way fixed ring.
            var base: int = c256 / 256;
            var k: int = 0;
            while k < 6 {
                var a: angle = (base + (k * 65536) / 6) as angle;
                _ = fire(TH14_BALL2, 2,
                         sx - 16fx * cos(a), sy - 16fx * sin(a),
                         4fx, a, none, none);
                k = k + 1;
            }
            w = w + 1;
        }
        c256 = c256 + WAVE_GAIN_256;
        wait(5);
        n = n + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
